import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/getting-started.md","filePath":"zh-CN/user-guide/getting-started.md","lastUpdated":1787551561000}'),d={name:"zh-CN/user-guide/getting-started.md"};function n(s,e,c,i,l,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>在首页的<a href="./../">下载按钮</a>获取最新版本——每次发布都会提供两种形式：</p><ul><li><strong>安装包</strong>（<code>Lertaro-Setup.exe</code>）—— 推荐使用。会注册后台索引服务，也可以设置为随 Windows 启动。</li><li><strong>便携版</strong>（<code>Lertaro-Portable.zip</code>）—— 解压即可运行，无需安装。之后仍然可以在 <strong>设置 → 运行状态</strong> 里手动安装后台服务。如果电脑上还没有 Lertaro 需要的 .NET 桌面运行时，运行一次自带的 <code>install-dotnet-runtime.bat</code> 即可——安装包会自动处理这一步，但便携版做不到。便携版用完不再需要时，没有卸载程序帮你清理：删除文件夹前，运行自带的 <code>portable-cleanup.bat</code>。它会在服务已安装时停止并卸载 Lertaro 后台服务，同时移除当前用户的 <code>lertaro://</code> URI 协议注册和&quot;开机自动启动&quot;注册项。卸载服务时可能会请求管理员权限，其余清理针对当前用户执行。</li></ul><p>这两种形式都分别提供 <strong>x64</strong> 和 <strong>ARM64</strong> 版本。上面这些是 x64 版本，在绝大多数电脑上都能运行——包括 Windows on ARM 设备，只是以模拟方式运行。如果用的是 ARM 设备，建议改用 <code>Lertaro-Setup-arm64.exe</code> 或 <code>Lertaro-Portable-arm64.zip</code>，它们是原生版本。自动更新会一直保持在你安装时的架构上，所以要换成另一种，需要自己去下载。</p><h2 id="便携版数据" tabindex="-1">便携版数据 <a class="header-anchor" href="#便携版数据" aria-label="Permalink to &quot;便携版数据&quot;">​</a></h2><p>便携版会在程序旁将机器数据保存到 <code>Data\\Machine</code>，并把每位用户的私有数据保存到 <code>Data\\Users\\&lt;SID hash&gt;</code>。如果其 <code>Data</code> 目录尚未创建，为了兼容会复用已有的 <code>%ProgramData%\\Lertaro</code> 和 <code>%LocalAppData%\\Lertaro</code> 数据；创建 <code>Data</code> 后，该便携版将优先使用自己的数据并成为自包含副本。</p><p>首次运行时，Lertaro 会安装并启动一个 Windows 服务（<code>Lertaro.Service</code>），专门负责文件索引。这个拆分是有意为之的——如果好奇原因可以参考<a href="./../dev-guide/architecture.html">架构设计</a>——但作为普通用户，只需要知道：<strong>设置 → 运行状态</strong> 页面会告诉你服务是否已安装、是否在运行，如果还没安装，也可以在这里安装。</p><h2 id="三种窗口" tabindex="-1">三种窗口 <a class="header-anchor" href="#三种窗口" aria-label="Permalink to &quot;三种窗口&quot;">​</a></h2><p>Lertaro 不是只有一个搜索窗口——它会根据使用场景自动适配：</p><ul><li><strong>主窗口</strong> —— 从任务栏/开始菜单快捷方式打开的完整窗口，结果列表最大，还带有窗内动作面板。</li><li><strong>快速窗口</strong> —— 按下全局呼出热键（默认双击 <code>Ctrl</code>）召唤出来的紧凑型置顶弹窗，专为&quot;按热键 → 输入 → 回车&quot;这套肌肉记忆设计。</li><li><strong>内嵌窗口</strong> —— 直接把 Lertaro 的搜索框嵌入到受支持的原生文件对话框或文件资源管理器窗口里，不用离开当前对话框就能搜索。</li></ul><p>三种窗口共用同一套搜索引擎、热键系统和动作菜单——区别只在于它们出现的位置和形态。</p><h2 id="基本搜索" tabindex="-1">基本搜索 <a class="header-anchor" href="#基本搜索" aria-label="Permalink to &quot;基本搜索&quot;">​</a></h2><p>最近文件、收藏夹和历史记录不用输入任何东西就能拿到——它们是<a href="./settings/quick-panel.html">快速面板</a>里的标签，而这个面板是叠在当前前台窗口上打开的，并不在搜索窗口里面。</p><p>直接开始打字即可。结果会随输入实时更新，并按相关度排序（匹配与排序的原理见<a href="./search-syntax.html">搜索语法</a>）。用<a href="./hotkeys.html">可配置的上/下一项热键</a>（默认是方向键）移动选中项，回车打开高亮的结果。</p><p>接下来可以看看 <a href="./search-syntax.html">搜索语法</a>，充分发挥搜索框的能力。</p>',16)])])}const g=a(d,[["render",n]]);export{u as __pageData,g as default};
